import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.D6hBiDio.js";const u=JSON.parse('{"title":"自编译固件","description":"在自编译 OpenWrt 固件中嵌入本仓库的最新 tailscale — build_feed.sh 用法与替代方案","frontmatter":{"title":"自编译固件","description":"在自编译 OpenWrt 固件中嵌入本仓库的最新 tailscale — build_feed.sh 用法与替代方案"},"headers":[],"relativePath":"zh/build/self-build.md","filePath":"zh/build/self-build.md","lastUpdated":1788749082000}'),s={name:"zh/build/self-build.md"};function d(o,e,r,h,n,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="自编译固件-buildroot" tabindex="-1">自编译固件 (Buildroot) <a class="header-anchor" href="#自编译固件-buildroot" aria-label="Permalink to &quot;自编译固件 (Buildroot)&quot;">​</a></h1><p>在自编译固件的 buildroot 中嵌入本仓库 tailscale 的指南。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li>自行编译 OpenWrt 固件，希望固件内置最新版 tailscale</li><li>官方 packages feed 的 tailscale 已停止更新（例如 24.10 冻结分支仍停留在旧版本）</li></ul><h2 id="方式一-预编译-ipk-直接安装-无需编译" tabindex="-1">方式一：预编译 ipk 直接安装（无需编译） <a class="header-anchor" href="#方式一-预编译-ipk-直接安装-无需编译" aria-label="Permalink to &quot;方式一：预编译 ipk 直接安装（无需编译）&quot;">​</a></h2><p>如果只是想让现有固件用上最新版，直接安装本仓库预编译的 ipk 即可——步骤与标准安装完全相同，见<a href="/openwrt-tailscale/zh/guide/manual-install.html">手动下载安装</a>，无需 buildroot。</p><blockquote><p>注意：固件升级后预安装的包会被恢复为固件内置版本，需要重新安装。</p></blockquote><h2 id="方式二-一键脚本-build-feed-sh" tabindex="-1">方式二：一键脚本 build_feed.sh <a class="header-anchor" href="#方式二-一键脚本-build-feed-sh" aria-label="Permalink to &quot;方式二：一键脚本 build_feed.sh&quot;">​</a></h2><p>在 buildroot 中自动完成：替换 Go 工具链 → 注册本仓库为 feed → 移除官方旧包 → 选中并编译。</p><h3 id="一行式运行-无需本地检出" tabindex="-1">一行式运行（无需本地检出） <a class="header-anchor" href="#一行式运行-无需本地检出" aria-label="Permalink to &quot;一行式运行（无需本地检出）&quot;">​</a></h3><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/GuNanOvO/openwrt-tailscale/main/build_scripts/build_feed.sh)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/openwrt/buildroot</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="本地模式-开发调试" tabindex="-1">本地模式（开发调试） <a class="header-anchor" href="#本地模式-开发调试" aria-label="Permalink to &quot;本地模式（开发调试）&quot;">​</a></h3><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build_scripts/build_feed.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/openwrt/buildroot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/openwrt-tailscale</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>第二个参数指向本仓库的本地检出目录，以 <code>src-link</code> 方式挂载。</p><h3 id="常用参数" tabindex="-1">常用参数 <a class="header-anchor" href="#常用参数" aria-label="Permalink to &quot;常用参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>--no-compile</code></td><td>只配置 feed 与勾选包，不编译（隐含 <code>--no-index</code>）</td></tr><tr><td><code>--no-index</code></td><td>跳过 <code>make package/index</code></td></tr><tr><td><code>--go-version &lt;版本&gt;</code></td><td>固定 Go 工具链版本（默认自动检测最新稳定版）</td></tr><tr><td><code>-h</code> / <code>--help</code></td><td>显示完整帮助</td></tr></tbody></table><p>其他环境变量：<code>JOBS</code>（并行度）、<code>REPO_URL</code>（镜像地址）、<code>GO_VERSION</code>（固定 Go 版本）。</p><h3 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h3><ol><li>确定 Go 版本（未指定时自动检测，离线回退 1.26.6）</li><li>用 <code>prepare_go_for_openwrt.sh</code> 覆盖 buildroot 自带 Go</li><li>注册 <code>openwrt_tailscale</code> feed</li><li>移除其他 feed 中的官方 tailscale 链接</li><li>安装本仓库包并勾选 <code>CONFIG_PACKAGE_tailscale=y</code></li><li>编译并校验产物</li></ol><p>脚本可重复执行：<code>./scripts/feeds update -a</code> 后官方旧包会复活，重跑一次脚本即可恢复。</p><h2 id="手动步骤-备选" tabindex="-1">手动步骤（备选） <a class="header-anchor" href="#手动步骤-备选" aria-label="Permalink to &quot;手动步骤（备选）&quot;">​</a></h2><p>如果希望完全手动操作，详见仓库内的 <code>package/tailscale/FORK.md</code>。</p><h2 id="维护说明" tabindex="-1">维护说明 <a class="header-anchor" href="#维护说明" aria-label="Permalink to &quot;维护说明&quot;">​</a></h2><p><code>build_feed.sh</code> 为社区贡献（由 <a href="https://github.com/Potterli20" target="_blank" rel="noreferrer">@Potterli20</a> 维护，源自 <a href="https://github.com/GuNanOvO/openwrt-tailscale/issues/142" target="_blank" rel="noreferrer">issue #142</a>），不在本仓库核心分发流程内。脚本问题请通过 <a href="https://github.com/GuNanOvO/openwrt-tailscale/pulls" target="_blank" rel="noreferrer">GitHub PR</a> 提交。</p>',24)])])}const b=a(s,[["render",d]]);export{u as __pageData,b as default};
